import { Group, Mesh, PlaneGeometry, Color } from 'three/webgpu';
import {
  MeshStandardNodeMaterial,
  MeshBasicNodeMaterial,
} from 'three/webgpu';
import { color, mix, uv } from 'three/tsl';
import { gsap } from 'gsap';
import '@/primitives';
import '@/text';

export default function createNode(config, ctx) {
  const { Group: ThreeGroup } = ctx.THREE;

  // Root container (position/scale handled by adapter)
  const root = new ThreeGroup();

  // ---------- Contact Shadow ----------
  const shadowGeo = new PlaneGeometry(3.6, 0.5);
  const shadowMat = new MeshBasicNodeMaterial({
    color: new Color('#000000'),
    transparent: true,
    opacity: 0.35,
  });
  const shadowMesh = new Mesh(shadowGeo, shadowMat);
  shadowMesh.position.set(0, -0.06, 0); // offset down, Z = 0 (rail floats +0.15)
  root.add(shadowMesh);

  // ---------- Rail ----------
  const railGeo = new PlaneGeometry(3.6, 0.5);
  const railMat = new MeshStandardNodeMaterial();
  // vertical gradient albedo
  railMat.colorNode = mix(
    color('#1b1b23'),
    color('#101015'),
    uv().y
  );
  railMat.metalness = 0.5;
  railMat.roughness = 0.55;
  railMat.clearcoat = 0.2;
  railMat.anisotropy = 0.6;
  const railMesh = new Mesh(railGeo, railMat);
  railMesh.position.set(0, 0, 0.15); // floating rail
  root.add(railMesh);

  // ---------- Text Entries ----------
  const entriesSpec = [
    { label: 'HOME', role: 'nav-active' },
    { label: 'FEATURES', role: 'nav-item' },
    { label: 'COLLECTION', role: 'nav-item' },
    { label: 'PRICING', role: 'nav-item' },
    { label: 'JOURNAL', role: 'nav-item' },
  ];

  const entryGroups = [];
  const timelines = [];
  let activeIndex = 0;
  const underlineGroup = new Group();

  // underline (initially under active entry)
  const underlineGeo = new PlaneGeometry(0.28, 0.025);
  const underlineMat = new MeshStandardNodeMaterial({
    color: new Color('#ff2a38'),
    emissive: new Color('#ff2a38'),
    emissiveIntensity: 1.8,
  });
  const underlineMesh = new Mesh(underlineGeo, underlineMat);
  underlineMesh.position.set(0, -0.06, 0.01);
  underlineGroup.add(underlineMesh);
  root.add(underlineGroup);

  entriesSpec.forEach((item, i) => {
    const entry = new Group();
    const xPos = (i - 2) * 0.68; // center spacing
    entry.position.set(xPos, 0, 0.18); // slightly in front of rail
    const isActive = i === activeIndex;

    // Text creation
    const txtColor = isActive ? '#e8ecf2' : '#a6adba';
    const txt = ctx.fontAtlas.createText(item.label, {
      fontSize: 13,
      color: txtColor,
      align: 'center',
      letterSpacing: 1.04, // 0.08 * 13
    });
    entry.add(txt);

    // Store reference to text mesh for color changes
    let textMesh = null;
    txt.traverse((obj) => {
      if (obj.isMesh) textMesh = obj;
    });

    // Handlers
    const originalZ = entry.position.z;
    const hoverTimeline = gsap.timeline({ paused: true });
    const pressTimeline = gsap.timeline({ paused: true });
    const releaseTimeline = gsap.timeline({ paused: true });

    entry.userData.handlers = {
      pointerover: () => {
        if (i !== activeIndex) {
          hoverTimeline.clear();
          hoverTimeline.to(
            textMesh.material,
            {
              color: new Color('#e8ecf2'),
              duration: 0.16,
              ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
            },
            0
          );
          hoverTimeline.play(0);
        }
      },
      pointerout: () => {
        if (i !== activeIndex) {
          hoverTimeline.clear();
          hoverTimeline.to(
            textMesh.material,
            {
              color: new Color('#a6adba'),
              duration: 0.16,
              ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
            },
            0
          );
          hoverTimeline.play(0);
        }
      },
      pointerdown: () => {
        pressTimeline.clear();
        pressTimeline
          .to(entry.scale, { x: 0.97, y: 0.97, z: 0.97, duration: 0.12, ease: 'cubic-bezier(0.175,0.885,0.32,1.275)' })
          .to(entry.position, { z: originalZ - 0.03, duration: 0.12, ease: 'cubic-bezier(0.175,0.885,0.32,1.275)' }, 0);
        pressTimeline.play(0);
      },
      pointerup: () => {
        releaseTimeline.clear();
        releaseTimeline
          .to(entry.scale, { x: 1, y: 1, z: 1, duration: 0.12, ease: 'cubic-bezier(0.175,0.885,0.32,1.275)' })
          .to(entry.position, { z: originalZ, duration: 0.12, ease: 'cubic-bezier(0.175,0.885,0.32,1.275)' }, 0);
        releaseTimeline.play(0);
      },
      click: () => {
        if (i === activeIndex) return;
        // change previous active
        const prev = entryGroups[activeIndex];
        const prevTxt = prev.children[0];
        let prevMesh = null;
        prevTxt.traverse((obj) => {
          if (obj.isMesh) prevMesh = obj;
        });
        gsap.to(prevMesh.material, {
          color: new Color('#a6adba'),
          duration: 0.16,
          ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
        });
        // new active
        gsap.to(textMesh.material, {
          color: new Color('#e8ecf2'),
          duration: 0.16,
          ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
        });
        // move underline
        gsap.to(underlineGroup.position, {
          x: entry.position.x,
          duration: 0.26,
          ease: 'cubic-bezier(0.165,0.84,0.44,1)',
          onComplete: () => {
            gsap.to(underlineGroup.scale, { x: 1.04, duration: 0.1, yoyo: true, repeat: 1 });
          },
        });
        activeIndex = i;
        // navigation event (based on label lowercased)
        ctx.emit('navigate', { to: `hub-${item.label.toLowerCase()}` });
      },
    };

    // store timelines for cleanup
    timelines.push(hoverTimeline, pressTimeline, releaseTimeline);
    entryGroups.push(entry);
    root.add(entry);
  });

  // ---------- Mount animation ----------
  gsap.from(root.position, {
    y: 0.4,
    duration: 0.7,
    ease: 'cubic-bezier(0.215,0.61,0.355,1)',
  });

  // ---------- Cleanup ----------
  root.userData.cleanup = () => {
    // dispose materials
    railMat.dispose();
    shadowMat.dispose();
    underlineMat.dispose();
    // dispose any extra materials inside text meshes
    entryGroups.forEach((g) => {
      g.traverse((obj) => {
        if (obj.isMesh && obj.material && obj.material.dispose) {
          obj.material.dispose();
        }
      });
    });
    // kill timelines
    timelines.forEach((tl) => tl.kill());
  };

  return root;
}
